fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    let maxsplit_usize = maxsplit as usize;
    
    a.into_iter()
        .map(|s| {
            if maxsplit == 0 {
                // No splitting, return single element vec
                vec![s]
            } else if s.is_empty() {
                // Empty string splits to vec with empty string
                vec![String::new()]
            } else {
                // Perform right split up to maxsplit times (maxsplit + 1 parts)
                // rsplitn returns parts starting from the right, so reverse afterwards
                let mut parts: Vec<String> = s
                    .rsplitn(maxsplit_usize + 1, &sep)
                    .map(|part| part.to_string())
                    .collect();
                parts.reverse();
                parts
            }
        })
        .collect()
}